/// The parameters of scene.switch.
/// </summary>
public sealed record SceneSwitchParams
{
    /// <summary>
    /// This switch only: how long it takes (Layer by layer takes as long as its layers' own shows and hides).
    /// </summary>
    [JsonPropertyName("duration_ms")]
    public long? DurationMs { get; init; }

    /// <summary>
    /// This switch only: play it backward with its pictures swapped.
    /// </summary>
    [JsonPropertyName("reverse")]
    public bool? Reverse { get; init; }

    /// <summary>
    /// The scene to put on air. Give its id or name.
    /// </summary>
    [JsonPropertyName("scene")]
    public required string Scene { get; init; }

    /// <summary>
    /// This switch only: a type (fade, slide, move, layer_by_layer…), an effect, a pack transition or a saved transition's name, as for transition.set. Left out, the scene's own or the default plays.
    /// </summary>
    [JsonPropertyName("transition")]
    public string? Transition { get; init; }
}

/// <summary>
/// The transition this switch played, when it was given one of its own.
/// </summary>
