{
    /// <summary>
    /// How long it takes; a stinger lasts as long as its video.
    /// </summary>
    [JsonPropertyName("duration_ms")]
    public long DurationMs { get; init; }

    /// <summary>
    /// Its saved name, else its type's (or effect's, or pack transition's) name.
    /// </summary>
    [JsonPropertyName("name")]
    public string Name { get; init; } = "";

    /// <summary>
    /// Whether it plays backward with its pictures swapped.
    /// </summary>
    [JsonPropertyName("reverse")]
    public bool Reverse { get; init; }

    /// <summary>
    /// cut, fade, fade_to_color, slide, swipe, luma_wipe, move, effect, shader, pack or stinger.
    /// </summary>
    [JsonPropertyName("type")]
    public string Type { get; init; } = "";
}

