/// <summary>
/// Which kind of EmoteSectionIcon it is.
/// </summary>
[JsonConverter(typeof(EmoteSectionIconKindJsonConverter))]
public enum EmoteSectionIconKind
{
    /// <summary>A word this version of the SDK doesn't know: a newer Studio sent it. Regenerate to get it.</summary>
    Unknown = 0,
    /// <summary><c>mark</c></summary>
    Mark,
    /// <summary><c>service</c></summary>
    Service,
    /// <summary><c>image</c></summary>
    Image,
    /// <summary><c>glyph</c></summary>
    Glyph,
    /// <summary><c>symbol</c></summary>
    Symbol,
    /// <summary><c>initial</c></summary>
    Initial,
}

internal sealed class EmoteSectionIconKindJsonConverter : JsonConverter<EmoteSectionIconKind>
{
    public override EmoteSectionIconKind Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options) => EmoteSectionIconKindWire.Parse(reader.GetString());
    public override void Write(Utf8JsonWriter writer, EmoteSectionIconKind value, JsonSerializerOptions options) => writer.WriteStringValue(value.ToWire());
}

/// <summary>EmoteSectionIconKind to and from the words on the wire.</summary>
public static class EmoteSectionIconKindWire
{
    /// <summary>The word Studio uses for <paramref name="value"/>.</summary>
    public static string ToWire(this EmoteSectionIconKind value) => value switch
    {
        EmoteSectionIconKind.Mark => "mark",
        EmoteSectionIconKind.Service => "service",
        EmoteSectionIconKind.Image => "image",
        EmoteSectionIconKind.Glyph => "glyph",
        EmoteSectionIconKind.Symbol => "symbol",
        EmoteSectionIconKind.Initial => "initial",
        _ => throw new ArgumentOutOfRangeException(nameof(value), value, "EmoteSectionIconKind.Unknown can't be sent to Studio"),
    };

    /// <summary>The value for a word from Studio; <see cref="EmoteSectionIconKind.Unknown"/> for one this SDK doesn't know.</summary>
    public static EmoteSectionIconKind Parse(string? word) => word switch
    {
        "mark" => EmoteSectionIconKind.Mark,
        "service" => EmoteSectionIconKind.Service,
        "image" => EmoteSectionIconKind.Image,
        "glyph" => EmoteSectionIconKind.Glyph,
        "symbol" => EmoteSectionIconKind.Symbol,
        "initial" => EmoteSectionIconKind.Initial,
        _ => EmoteSectionIconKind.Unknown,
    };
}

