/// <summary>
/// Which kind of ChatPart it is.
/// </summary>
[JsonConverter(typeof(ChatPartKindJsonConverter))]
public enum ChatPartKind
{
    /// <summary>A word this version of the SDK doesn't know: a newer Studio sent it. Regenerate to get it.</summary>
    Unknown = 0,
    /// <summary><c>text</c></summary>
    Text,
    /// <summary><c>emote</c></summary>
    Emote,
    /// <summary><c>mention</c></summary>
    Mention,
    /// <summary><c>link</c></summary>
    Link,
    /// <summary><c>styled</c></summary>
    Styled,
}

internal sealed class ChatPartKindJsonConverter : JsonConverter<ChatPartKind>
{
    public override ChatPartKind Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options) => ChatPartKindWire.Parse(reader.GetString());
    public override void Write(Utf8JsonWriter writer, ChatPartKind value, JsonSerializerOptions options) => writer.WriteStringValue(value.ToWire());
}

/// <summary>ChatPartKind to and from the words on the wire.</summary>
public static class ChatPartKindWire
{
    /// <summary>The word Studio uses for <paramref name="value"/>.</summary>
    public static string ToWire(this ChatPartKind value) => value switch
    {
        ChatPartKind.Text => "text",
        ChatPartKind.Emote => "emote",
        ChatPartKind.Mention => "mention",
        ChatPartKind.Link => "link",
        ChatPartKind.Styled => "styled",
        _ => throw new ArgumentOutOfRangeException(nameof(value), value, "ChatPartKind.Unknown can't be sent to Studio"),
    };

    /// <summary>The value for a word from Studio; <see cref="ChatPartKind.Unknown"/> for one this SDK doesn't know.</summary>
    public static ChatPartKind Parse(string? word) => word switch
    {
