    [JsonPropertyName("label")]
    public string? Label { get; init; }

    /// <summary>
    /// Its name on the wire.
    /// </summary>
    [JsonPropertyName("name")]
    public string Name { get; init; } = "";

    /// <summary>
    /// The sources it carries; null for the stream mix (Studio's track 1).
    /// </summary>
    [JsonPropertyName("sources")]
    public IReadOnlyList<string>? Sources { get; init; }
}

public sealed record VeloqState
{
    /// <summary>
    /// The collection has a stinger (its sound plays through the Transitions channel).
    /// </summary>
    [JsonPropertyName("has_stinger")]
    public bool HasStinger { get; init; }

    /// <summary>
    /// The viewer's mixer as Velora's player builds it from those tracks.
    /// </summary>
    [JsonPropertyName("mixer")]
    public ViewerMixer Mixer { get; init; } = new();

    /// <summary>
    /// Sources that never leave Studio.
    /// </summary>
    [JsonPropertyName("not_sent")]
    public IReadOnlyList<string> NotSent { get; init; } = [];

    /// <summary>
    /// How many there are (8).
    /// </summary>
    [JsonPropertyName("slider_limit")]
    public long SliderLimit { get; init; }

    /// <summary>
    /// Viewer sliders taken by sources and sends.
    /// </summary>
    [JsonPropertyName("sliders_used")]
    public long SlidersUsed { get; init; }

    /// <summary>
    /// The audio tracks a VELoQ Go Live sends, in order (the stream mix first).
    /// </summary>
    [JsonPropertyName("tracks")]
    public IReadOnlyList<VeloqTrack> Tracks { get; init; } = [];

    /// <summary>
    /// Where stinger sounds go for viewers.
    /// </summary>
    [JsonPropertyName("transitions")]
    public VeloqVisibility Transitions { get; init; }
}

public sealed record WebPage
{
    /// <summary>
    /// Failed tries in a row.
    /// </summary>
    [JsonPropertyName("attempts")]
    public long Attempts { get; init; }

    /// <summary>
    /// Whether it can be loaded again now (its page is open).
    /// </summary>
    [JsonPropertyName("can_reload")]
    public bool CanReload { get; init; }

    /// <summary>
    /// Why it failed: connection_refused, cannot_connect, name_not_resolved, timed_out, offline, connection_reset, unreachable, certificate, bad_response, file_not_found, http_error, other, or engine (the web engine itself couldn't run); null unless failed.
    /// </summary>
    [JsonPropertyName("code")]
    public string? Code { get; init; }

    /// <summary>
    /// The main document's HTTP status, when that's why it failed.
    /// </summary>
    [JsonPropertyName("http_status")]
    public long? HttpStatus { get; init; }

    [JsonPropertyName("id")]
    public string Id { get; init; } = "";

    /// <summary>
    /// Why it failed, in plain words ("Can't reach localhost:3000 (connection refused)"); null unless failed.
    /// </summary>
    [JsonPropertyName("message")]
    public string? Message { get; init; }

    [JsonPropertyName("name")]
    public string Name { get; init; } = "";

    /// <summary>
    /// When the next try starts (Unix ms); null while one is under way or nothing failed.
    /// </summary>
    [JsonPropertyName("retry_at_ms")]
    public long? RetryAtMs { get; init; }

    /// <summary>
    /// idle (not in use), loading, ok, or failed: then it's see-through on air and tried again by itself (2 s, 5 s, 10 s, then every 30 s).
    /// </summary>
    [JsonPropertyName("state")]
    public WebPageState State { get; init; }

    /// <summary>
    /// The address it's loading or that failed.
    /// </summary>
    [JsonPropertyName("url")]
    public string? Url { get; init; }
}

public sealed record WebState
{
    [JsonPropertyName("items")]
    public IReadOnlyDictionary<string, WebPage> Items { get; init; } = new Dictionary<string, WebPage>();
}
